fn traverse_subtree(
    element: GeckoElement,
    global_style_data: &GlobalStyleData,
    per_doc_data: &PerDocumentStyleDataImpl,
    guard: &SharedRwLockReadGuard,
    traversal_flags: TraversalFlags,
    snapshots: &ServoElementSnapshotTable,
) {
    let shared_style_context = create_shared_context(
        &global_style_data,
        &guard,
        &per_doc_data.stylist,
        traversal_flags,
        snapshots,
    );

    let token = RecalcStyleOnly::pre_traverse(element, &shared_style_context);

    if !token.should_traverse() {
        return;
    }

    debug!("Traversing subtree from {:?}", element);

    let thread_pool_holder = &*STYLE_THREAD_POOL;
    let pool;
    let thread_pool = if traversal_flags.contains(TraversalFlags::ParallelTraversal) {
        pool = thread_pool_holder.pool();
        pool.as_ref()
    } else {
        None
    };

    let traversal = RecalcStyleOnly::new(shared_style_context);
    let root = driver::traverse_dom(&traversal, token, thread_pool);
    if traversal.needs_normal_descendant_restyle() {
        let mut has_styled_child = false;
        for child_node in root.traversal_children() {
            let Some(child) = child_node.as_element() else {
                continue;
            };
            let mut child_data = child.mutate_data();
            let Some(child_data) = child_data.as_mut() else {
                continue;
            };
            if !child_data.has_styles() {
                continue;
            }
            child_data
                .hint
                .insert(RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT);
            has_styled_child = true;
        }
        if has_styled_child {
            unsafe { root.set_dirty_descendants() };
        }
    }
}

